def render_figure(self: Any, text: str, align: Optional[str]=None, figwidth:
    Optional[str]=None, figclass: Optional[str]=None) ->str:
    attrs = ''
    style = ''

    if figwidth:
        if figwidth.isdigit():
            style += 'width:' + figwidth + 'px;'
        else:
            style += 'width:' + figwidth + ';'

    if style:
        attrs += ' style="' + style + '"'

    _cls = 'figure'
    if align:
        _cls += ' align-' + align
    if figclass:
        _cls += ' ' + figclass

    attrs += ' class="' + _cls + '"'

    return '<figure' + attrs + '>\n' + text + '</figure>\n'
